// PLANTILLA DE RESPALDO FE V2 (modo emergencia): sirve para cualquier oración, salmo o historia.
// No depende de palabras: los momentos van por fracción de la duración (DUR). Noche -> amanecer, una luz cálida,
// tres profundidades, movimiento lento y continuo. Voz, música, subtítulos y acabado los pone render_fe.py.
import React from 'react';
import {AbsoluteFill, Easing, interpolate} from 'remotion';
import {useS, clamp, DUR} from './kit';

const W = 1080;
const H = 1920;
const D = Math.max(DUR, 10);
const AMANECE = D * 0.45;
const CAMINO = D * 0.62;
const ABRAZO = D * 0.8;

const mezcla = (a: number[], b: number[], k: number) => `rgb(${a.map((x, i) => Math.round(x + (b[i] - x) * k)).join(',')})`;

const Colina: React.FC<{y: number; alto: number; color: [string, string]; deriva: number; borde: number}> = ({y, alto, color, deriva, borde}) => (
  <svg width={W + 200} height={alto} style={{position: 'absolute', left: -100 + deriva, top: y}} viewBox={`0 0 ${W + 200} ${alto}`}>
    <defs>
      <linearGradient id={`p${y}`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={color[0]} />
        <stop offset="100%" stopColor={color[1]} />
      </linearGradient>
    </defs>
    <path d={`M0 ${alto * 0.45} C ${W * 0.25} ${alto * 0.1}, ${W * 0.45} ${alto * 0.5}, ${W * 0.65} ${alto * 0.25} S ${W + 120} ${alto * 0.2}, ${W + 200} ${alto * 0.35} L ${W + 200} ${alto} L 0 ${alto} Z`} fill={`url(#p${y})`} />
    <path d={`M0 ${alto * 0.45} C ${W * 0.25} ${alto * 0.1}, ${W * 0.45} ${alto * 0.5}, ${W * 0.65} ${alto * 0.25} S ${W + 120} ${alto * 0.2}, ${W + 200} ${alto * 0.35}`} fill="none" stroke="rgba(255,226,170,0.8)" strokeWidth={4} opacity={borde} />
  </svg>
);

export const Escena: React.FC = () => {
  const {s} = useS();
  const k = interpolate(s, [AMANECE - 0.5, AMANECE + 5], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const camino = interpolate(s, [CAMINO, CAMINO + 3], [0, 1], {...clamp, easing: Easing.inOut(Easing.quad)});
  const abrazo = interpolate(s, [ABRAZO, ABRAZO + 2], [0, 1], clamp);
  const zoom = 1.08 - 0.06 * (s / D);
  const deriva = Math.sin(s * 0.15) * 20;
  const solY = interpolate(k, [0, 1], [1500, 880], clamp);
  const respira = Math.sin(s * 1.4) * 3;
  return (
    <AbsoluteFill style={{overflow: 'hidden', backgroundColor: '#0a0f24'}}>
      <AbsoluteFill style={{transform: `scale(${zoom}) translateX(${deriva}px)`, transformOrigin: '50% 60%'}}>
        <AbsoluteFill style={{background: `linear-gradient(180deg, ${mezcla([10, 16, 40], [72, 110, 170], k)} 0%, ${mezcla([22, 30, 66], [236, 170, 120], k)} 62%, ${mezcla([30, 34, 70], [255, 214, 150], k)} 100%)`}} />
        <AbsoluteFill style={{opacity: 1 - k}}>
          {Array.from({length: 70}).map((_, i) => {
            const r = 1.5 + (i % 3);
            return <div key={i} style={{position: 'absolute', left: (i * 157) % W, top: (i * 263) % 1050, width: r * 2, height: r * 2, borderRadius: r, background: '#fff8e0', opacity: 0.45 + 0.55 * Math.abs(Math.sin(s * 0.8 + i)), boxShadow: '0 0 8px #fff3c4'}} />;
          })}
        </AbsoluteFill>
        <div style={{position: 'absolute', left: W / 2 - 450, top: solY - 450, width: 900, height: 900, opacity: k}}>
          <div style={{position: 'absolute', inset: 0, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,226,160,0.55) 0%, rgba(255,190,120,0.18) 35%, transparent 70%)'}} />
          <div style={{position: 'absolute', left: 300, top: 300, width: 300, height: 300, borderRadius: '50%', background: 'radial-gradient(circle at 40% 35%, #fffbe8 0%, #ffd98a 55%, #f3a95c 100%)', boxShadow: '0 0 120px 40px rgba(255,210,140,0.45)'}} />
        </div>
        <AbsoluteFill style={{opacity: k * 0.55, mixBlendMode: 'screen'}}>
          {Array.from({length: 9}).map((_, i) => (
            <div key={i} style={{position: 'absolute', left: W / 2 - 40, top: 880, width: 80, height: 1700, transformOrigin: '50% 0%', transform: `rotate(${140 + i * 10 + Math.sin(s * 0.3 + i) * 2}deg)`, background: 'linear-gradient(180deg, rgba(255,236,190,0.55), transparent 80%)', filter: 'blur(14px)'}} />
          ))}
        </AbsoluteFill>
        <Colina y={1000} alto={520} color={k > 0.5 ? ['#7a6a8e', '#4a3e62'] : ['#2a2f55', '#171a36']} deriva={deriva * 0.3} borde={k} />
        <div style={{position: 'absolute', left: 640, top: 1180, width: 180, height: 150}}>
          <div style={{position: 'absolute', left: 0, top: 50, width: 180, height: 100, background: 'linear-gradient(90deg, #1a1d36, #10122a)', borderRadius: 6}} />
          <div style={{position: 'absolute', left: -12, top: 0, width: 0, height: 0, borderLeft: '102px solid transparent', borderRight: '102px solid transparent', borderBottom: '56px solid #14162e'}} />
          <div style={{position: 'absolute', left: 70, top: 78, width: 40, height: 44, background: '#ffd48a', borderRadius: 4, opacity: 1 - k * 0.6, boxShadow: '0 0 40px 16px rgba(255,200,120,0.6)'}} />
        </div>
        <Colina y={1160} alto={760} color={k > 0.5 ? ['#5e5a7a', '#2c2840'] : ['#1d2244', '#0e1028']} deriva={deriva * 0.6} borde={k * 0.8} />
        <svg width={W} height={700} style={{position: 'absolute', left: 0, top: 1220}} viewBox={`0 0 ${W} 700`}>
          <path d="M380 700 C 470 520, 600 420, 540 300 S 560 120, 540 40 L 560 40 C 590 130, 600 210, 600 300 S 560 520, 700 700 Z" fill="#f6dfae" opacity={0.85} style={{clipPath: `inset(${(1 - camino) * 100}% 0 0 0)`}} />
        </svg>
        <div style={{position: 'absolute', left: 470, top: 1400 + respira}}>
          <div style={{position: 'absolute', left: -120, top: -140, width: 380, height: 380, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,226,160,0.6), transparent 70%)', opacity: abrazo}} />
          <svg width={140} height={300} viewBox="0 0 140 300">
            <ellipse cx={70} cy={292} rx={50} ry={8} fill="rgba(0,0,0,0.35)" />
            <circle cx={70} cy={48} r={34} fill="#191a30" />
            <path d="M22 140 Q 70 80 118 140 L 128 288 L 12 288 Z" fill="#191a30" />
          </svg>
        </div>
        <AbsoluteFill>
          {Array.from({length: 40}).map((_, i) => {
            const r = 3 + (i % 4);
            return <div key={i} style={{position: 'absolute', left: (i * 131) % W + Math.sin(s * 0.5 + i) * 30, top: H - ((i * 211 + s * (18 + (i % 5) * 6)) % (H + 100)), width: r, height: r, borderRadius: r, background: k > 0.5 ? '#ffe3a6' : '#dfe6ff', opacity: 0.35 + 0.3 * Math.sin(s + i), filter: 'blur(1px)'}} />;
          })}
        </AbsoluteFill>
      </AbsoluteFill>
      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 55%, transparent 55%, rgba(5,6,20,0.55) 100%)'}} />
    </AbsoluteFill>
  );
};
